import{_ as o,a0 as p,w as n,s as l,I as a,x as s,a1 as d,A as t,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"RTFM！如何阅读（和理解）Linux 中神奇的手册页 | LCTT x X-CMD","titleTemplate":false,"description":"RTFM！如何阅读（和理解）Linux 中神奇的手册页 | LCTT (202106) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"RTFM！如何阅读（和理解）Linux 中神奇的手册页 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"RTFM！如何阅读（和理解）Linux 中神奇的手册页 | LCTT (202106) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202106/20210611 RTFM- How to Read (and Understand) the Fantastic Man Pages in Linux","title":"RTFM！如何阅读（和理解）Linux 中神奇的手册页","tag":"202106","desc":""},"relativePath":"202106/20210611 RTFM- How to Read (and Understand) the Fantastic Man Pages in Linux.md","filePath":"[post].md"}'),r={name:"202106/20210611 RTFM- How to Read (and Understand) the Fantastic Man Pages in Linux.md"};function h(g,e,u,k,m,b){const i=p("Link");return n(),l("div",null,[e[18]||(e[18]=a("h1",{id:"rtfm-如何阅读-和理解-linux-中神奇的手册页",tabindex:"-1"},[s("RTFM！如何阅读（和理解）Linux 中神奇的手册页 "),a("a",{class:"header-anchor",href:"#rtfm-如何阅读-和理解-linux-中神奇的手册页","aria-label":"Permalink to “RTFM！如何阅读（和理解）Linux 中神奇的手册页”"},"​")],-1)),e[19]||(e[19]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202106/12/161749re6iiuhzn9ni2in4.jpg",alt:""})],-1)),e[20]||(e[20]=a("p",null,[a("ruby",null,[s("手册页"),a("rt",null,"man pages")]),s("，即"),a("ruby",null,[s("参考手册页"),a("rt",null,"reference manual pages")]),s("的简称，是你进入 Linux 的钥匙。你想知道的一切都在那里，包罗万象。这套文档永远不会赢得普利策奖，但这套文档是相当准确和完整的。手册页是主要信源，其权威性是众所周知的。")],-1)),a("p",null,[e[1]||(e[1]=s("虽然它们是源头，但阅读起来并不是最令人愉快的。有一次，在很久以前的哲学课上，有人告诉我，阅读 ",-1)),d(i,{href:"https://www.britannica.com/biography/Aristotle"},{default:t(()=>[...e[0]||(e[0]=[s("亚里士多德",-1)])]),_:1}),e[2]||(e[2]=s(" 是最无聊的阅读。我不同意：说到枯燥的阅读，亚里士多德远远地排在第二位，仅次于手册页。",-1))]),e[21]||(e[21]=c(`<p>乍一看，这些页面可能看起来并不完整，但是，不管你信不信，手册页并不是为了隐藏信息 —— 只是因为信息量太大，这些页面必须要有结构，而且信息是以尽可能简短的形式给出的。这些解释相当简略，需要一些时间来适应，但一旦你掌握了使用它们的技巧，你就会发现它们实际上是多么有用。</p><h3 id="linux-中的手册页入门" tabindex="-1">Linux 中的手册页入门 <a class="header-anchor" href="#linux-中的手册页入门" aria-label="Permalink to “Linux 中的手册页入门”">​</a></h3><p>这些页面是通过一个叫做 <code>man</code> 的工具查看的，使用它的命令相当简单。在最简单的情况下，要使用 <code>man</code>，你要在命令行上输入 <code>man</code>，后面加一个空格和你想查询的命令，比如 <code>ls</code> 或 <code>cp</code>，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man ls</span></span></code></pre></div><p><code>man</code> 会打开 <code>ls</code> 命令的手册页。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/man-page-example-800x527.png?resize=800%2C527&amp;ssl=1" alt=""></p><p>你可以用方向键上下移动，按 <code>q</code> 退出查看手册页。通常情况下，手册页是用 <code>less</code> 打开的，所以 <code>less</code> 命令的键盘快捷键在 <code>man</code> 中也可以使用。</p><p>例如，你可以用 <code>/search_term</code> 来搜索一个特定的文本，等等。</p><p>有一个关于手册页的介绍，这是一篇值得阅读介绍。它非常详细地说明了手册页是如何布局和组织的。</p><p>要看这个页面，请打开一个终端，然后输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man man</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/man_man.png?resize=800%2C455&amp;ssl=1" alt="man page of man"></p><h3 id="节" tabindex="-1">节 <a class="header-anchor" href="#节" aria-label="Permalink to “节”">​</a></h3><p>在你开始更深入地研究手册页之前，知道手册页有一个固定的页面布局和一个归档方案会有帮助。这可能会让新手感到困惑，因为我可以说：“看手册页中关于 <code>ls</code> 的 NAME <ruby>节<rt>section</rt></ruby>”，我也可以说：“看第 5 <ruby>节<rt>section</rt></ruby>中的 <code>passwd</code> 的手册页。”</p><p>我把 “<ruby>节<rt>section</rt></ruby>” 这个词用斜体字表示，是为了显示混淆的来源。这个词，“节” 被用于两种不同的方式，但并不总是向新人解释其中的区别。</p><p>我不确定为什么会出现这种混淆，但我在培训新用户和初级系统管理员时看到过几次这种混淆。我认为这可能是隧道视野，专注于一件事会使一个人忘记另一件事。一叶障目，不见泰山。</p><p>对于那些已经知道其中的区别的人，你可以跳过这一小节。这一部分是针对那些刚接触到手册页的人。</p><p>这就是区别：</p><h4 id="对于手册页" tabindex="-1">对于手册页 <a class="header-anchor" href="#对于手册页" aria-label="Permalink to “对于手册页”">​</a></h4><p>单独的手册页是用来显示信息块的。例如，每个手册页都有一个“NAME”节，显示命令的名称和简短的描述。还会有另一个信息块，称为“SYNOPSIS”，显示该命令是如何使用的，以此类推。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/man-page-example-1.png?resize=800%2C527&amp;ssl=1" alt=""></p><p>每个手册页都会有这些，以及其他的标题。这些在各个手册页上的节，或者说标题，有助于保持事情的一致性和信息的分工。</p><h4 id="对于手册" tabindex="-1">对于手册 <a class="header-anchor" href="#对于手册" aria-label="Permalink to “对于手册”">​</a></h4><p>使用“节”，如 “查看第 5 节中的 <code>passwd</code> 的手册页”，是指整个手册的内容。当我们只看一页时，很容易忽略这一点，但是 <code>passwd</code> 手册页是同一本手册的一部分，该手册还有 <code>ls</code>、<code>rm</code>、<code>date</code>、<code>cal</code> 等的手册页。</p><p>整个 Linux 手册是巨大的；它有成千上万的手册页。其中一些手册页有专门的信息。有些手册页有程序员需要的信息，有些手册页有网络方面的独特信息，还有一些是系统管理员会感兴趣的。</p><p>这些手册页根据其独特的目的被分组。想想看，把整个手册分成几个章节 —— 每章有一个特定的主题。有 9 个左右的章节（非常大的章节）。碰巧的是，这些章节被称为“节”。</p><p>总结一下：</p><ul><li>手册中单页（我们称之为“手册页”）的节是由标题定义的信息块。</li><li>这个大的手册（所有页面的集合）中的章节，刚好被称为“节”。</li></ul><p>现在你知道区别了，希望本文的其余部分会更容易理解。</p><h3 id="手册页的节" tabindex="-1">手册页的节 <a class="header-anchor" href="#手册页的节" aria-label="Permalink to “手册页的节”">​</a></h3><p>你将会看到不同的手册页，所以让我们先研究一下各个页面的布局。</p><p>手册页被分成几个标题，它们可能因提供者不同而不同，但会有相似之处。一般的分类如下：</p><ul><li><code>NAME</code>（名称）</li><li><code>SYNOPSIS</code>（概要）</li><li><code>DESCRIPTION</code>（描述）</li><li><code>EXAMPLES</code>（例子）</li><li><code>DIAGNOSTICS</code>（诊断）</li><li><code>FILES</code>（文件）</li><li><code>LIMITS</code>（限制）</li><li><code>PORTABILITY</code>（可移植性）</li><li><code>SEE ALSO</code>（另见）</li><li><code>HISTORY</code>（历史）</li><li>WARNING<code>（警告）或 </code>BUGS\`（错误）</li><li><code>NOTES</code>（注意事项）</li></ul><p><code>NAME</code> - 在这个标题下是命令的名称和命令的简要描述。</p><p><code>SYNOPSIS</code> - 显示该命令的使用方法。例如，这里是 <code>cal</code> 命令的概要：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cal [Month] [Year]</span></span></code></pre></div><p>概要以命令的名称开始，后面是选项列表。概要采用命令行的一般形式；它显示了你可以输入的内容和参数的顺序。方括号中的参数（<code>[]</code>）是可选的；你可以不输入这些参数，命令仍然可以正常工作。不在括号内的项目必须使用。</p><p>请注意，方括号只是为了便于阅读。当你输入命令时，不应该输入它们。</p><p><code>DESCRIPTION</code> - 描述该命令或工具的作用以及如何使用它。这一节通常以对概要的解释开始，并说明如果你省略任何一个可选参数会发生什么。对于长的或复杂的命令，这一节可能会被细分。</p><p><code>EXAMPLES </code> - 一些手册页提供了如何使用命令或工具的例子。如果有这一节，手册页会尝试给出一些简单的使用例子，以及更复杂的例子来说明如何完成复杂的任务。</p><p><code>DIAGNOSTICS</code> - 本节列出了由命令或工具返回的状态或错误信息。通常不显示不言自明的错误和状态信息。通常会列出可能难以理解的信息。</p><p><code>FILES</code> - 本节包含了 UNIX 用来运行这个特定命令的补充文件的列表。这里，“补充文件”是指没有在命令行中指定的文件。例如，如果你在看 <code>passwd</code> 命令的手册，你可能会发现 <code>/etc/passwd</code> 列在这一节中，因为 UNIX 是在这里存储密码信息。</p><p><code>LIMITS</code> - 本节描述了一个工具的限制。操作系统和硬件的限制通常不会被列出，因为它们不在工具的控制范围内。</p><p><code>PORTABILITY</code> - 列出其他可以使用该工具的系统，以及该工具的其他版本可能有什么不同。</p><p><code>SEE ALSO</code> - 列出包含相关信息的相关手册页。</p><p><code>HISTORY</code> - 提供命令的简要历史，如它第一次出现的时间。</p><p><code>WARNING</code> - 如果有这个部分，它包含了对用户的重要建议。</p><p><code>NOTES</code> - 不像警告那样严重，但也是重要的信息。</p><p>同样，并不是所有的手册都使用上面列出的确切标题，但它们足够接近，可以遵循。</p><h3 id="手册的节" tabindex="-1">手册的节 <a class="header-anchor" href="#手册的节" aria-label="Permalink to “手册的节”">​</a></h3><p>整个 Linux 手册集合的手册页传统上被划分为有编号的节：</p><p><strong>第 1 节</strong>：Shell 命令和应用程序 <strong>第 2 节</strong>：基本内核服务 - 系统调用和错误代码 <strong>第 3 节</strong>：为程序员提供的库信息 <strong>第 4 节</strong>：网络服务 - 如果安装了 TCP/IP 或 NFS 设备驱动和网络协议 <strong>第 5 节</strong>：文件格式 - 例如：显示 <code>tar</code> 存档的样子 <strong>第 6 节</strong>：游戏 <strong>第 7 节</strong>：杂项文件和文档 <strong>第 8 节</strong>：系统管理和维护命令 <strong>第 9 节</strong>：不知名的内核规格和接口</p><p>将手册页分成这些组，可以使搜索更有效率。在我工作的地方，我有时会做一些编程工作，所以我花了一点时间看第 3 节的手册页。我也做一些网络方面的工作，所以我也知道要涉足网络部分。作为几个实验性机器的系统管理员，我在第 8 节花了很多时间。</p><p>将手册网归入特定的节（章节），使搜索信息更加容易 —— 无论是对需要搜索的人，还是对进行搜索的机器。</p><p>你可以通过名称旁边的数字来判断哪个手册页属于哪个部分。例如，如果你正在看 <code>ls</code> 的手册页，而页面的最上面写着。 <code>LS(1)</code>，那么你正在浏览第 1 节中的 <code>ls</code> 页面，该节包含关于 shell 命令和应用程序的页面。</p><p>下面是另一个例子。如果你在看 <code>passwd</code> 的手册页，页面的顶部显示: <code>PASSWD(1)</code>，说明你正在阅读第 1 节中描述 <code>passwd</code> 命令如何更改用户账户密码的手册页。如果你看到 <code>PASSWD(5)</code>，那么你正在阅读关于密码文件和它是如何组成的的手册页。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/man-page-passwd-command.png?resize=1026%2C676&amp;ssl=1" alt=""></p><p><code>passwd</code> 恰好是两个不同的东西：一个是命令的名称，一个是文件的名称。同样，第 1 节描述了命令，而第 5 节涉及文件格式。</p><p>括号中的数字是重要的线索 —— 这个数字告诉你正在阅读的页面来自哪一节。</p><h3 id="搜索一个特定的节" tabindex="-1">搜索一个特定的节 <a class="header-anchor" href="#搜索一个特定的节" aria-label="Permalink to “搜索一个特定的节”">​</a></h3><p>基本命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man -a name</span></span></code></pre></div><p>将在每一节中搜索由 <code>name</code> 标识的手册页，按数字顺序逐一显示。要把搜索限制在一个特定的部分，请在 <code>man</code> 命令中使用一个参数，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 1 name</span></span></code></pre></div><p>这个命令将只在手册页的第 1 节中搜索 <code>name</code>。使用我们前面的 <code>passwd</code> 例子，这意味着我们可以保持搜索的针对性。如果我想阅读 <code>passwd</code> 命令的手册页，我可以在终端输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 1 passwd</span></span></code></pre></div><p><code>man</code> 工具将只在第 1 节中搜索 <code>passwd</code> 并显示它。它不会在任何其他节中寻找 <code>passwd</code>。</p><p>这个命令的另一种方法是输入: <code>man passwd.1</code>。</p><h3 id="使用-man-k-来搜索包含某个关键词的所有手册页" tabindex="-1">使用 man -k 来搜索包含某个关键词的所有手册页 <a class="header-anchor" href="#使用-man-k-来搜索包含某个关键词的所有手册页" aria-label="Permalink to “使用 man -k 来搜索包含某个关键词的所有手册页”">​</a></h3><p>如果你想获得包含某个关键词的手册页的列表，<code>man</code> 命令中的 <code>-k</code> 选项（通常称为标志或开关）可以派上用场。例如，如果你想看一个关于 <code>ftp</code> 的手册列表，你可以通过输入以下内容得到这个列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man -k ftp</span></span></code></pre></div><p>在接下来的列表中，你可以选择一个特定的手册页来阅读：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/man-k_example.png?resize=800%2C200&amp;ssl=1" alt="man k example"></p><p>在某些系统上，在 <code>man -k</code> 工作之前，系统管理员需要运行一个叫做 <code>catman</code> 的工具。</p><h3 id="使用-whatis-和-whereis-命令来了解手册的各个节" tabindex="-1">使用 whatis 和 whereis 命令来了解手册的各个节 <a class="header-anchor" href="#使用-whatis-和-whereis-命令来了解手册的各个节" aria-label="Permalink to “使用 whatis 和 whereis 命令来了解手册的各个节”">​</a></h3><p>有两个有趣的工具可以帮助你搜索信息：<code>whatis</code>和 <code>whereis</code>。</p><h4 id="whatis" tabindex="-1">whatis <a class="header-anchor" href="#whatis" aria-label="Permalink to “whatis”">​</a></h4><p>有的时候，我们完全可以得到我们需要的信息。我们需要的信息有很大的机会是可以找到的 —— 找到它可能是一个小问题。</p><p>例如，如果我想看关于 <code>passwd</code> 文件的手册页，我在终端上输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man passwd</span></span></code></pre></div><p>我就会看到关于 <code>passwd</code> 命令所有信息的手册页，但没有关于 <code>passwd</code> 文件的内容。我知道 <code>passwd</code> 是一个命令，也有一个 <code>passwd</code> 文件，但有时，我可能会忘记这一点。这时我才意识到，文件结构在手册页中的不同节，所以我输入了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 4 passwd</span></span></code></pre></div><p>我得到这样的答复：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>No manual entry for passwd in section 4</span></span>
<span class="line"><span>See &#39;man 7 undocumented&#39; for help when manual pages are not available.</span></span></code></pre></div><p>又是一次健忘的失误。文件结构在 System V UNIX 页面的第 4 节中。几年前，当我建立文件时，我经常使用 <code>man 4 ...</code>；这仍然是我的一个习惯。那么它在 Linux 手册中的什么地方呢？</p><p>现在是时候调用 <code>whatis</code> 来纠正我了。为了做到这一点，我在我的终端中输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>whatis passwd</span></span></code></pre></div><p>然后我看到以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>passwd (1)           - change user password</span></span>
<span class="line"><span>passwd (1ssl)        - compute password hashes</span></span>
<span class="line"><span>passwd (5)           - the password file</span></span></code></pre></div><p>啊！<code>passwd</code> 文件的页面在第 5 节。现在没问题了，可以访问我想要的信息了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man 5 passwd</span></span></code></pre></div><p>然后我被带到了有我需要的信息的手册页。</p><p><code>whatis</code> 是一个方便的工具，可以用简短的一句话告诉你一个命令的作用。想象一下，你想知道 <code>cal</code> 是做什么的，而不想查看手册页。只要在命令提示符下键入以下内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>whatis cal</span></span></code></pre></div><p>你会看到这样的回应：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cal (1)              - displays a calendar and the date of Easter</span></span></code></pre></div><p>现在你知道了 <code>whatis</code> 命令，我可以告诉你一个秘密 —— 有一个 <code>man</code> 命令的等价物。为了得到这个，我们使用 <code>-f</code> 开关：<code>man -f ...</code>。</p><p>试试吧。在终端提示下输入 <code>whatis cal</code>。执行后就输入：<code>man -f cal</code>。两个命令的输出将是相同的：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/05/whatis_cal_man-f_cal.png?resize=800%2C135&amp;ssl=1" alt="whatis cal and man f cal outputs are the same"></p><h4 id="whereis" tabindex="-1">whereis <a class="header-anchor" href="#whereis" aria-label="Permalink to “whereis”">​</a></h4><p><code>whereis</code> 命令的名字就说明了这一点 —— 它告诉你一个程序在文件系统中的位置。它也会告诉你手册页的存放位置。再以 <code>cal</code> 为例，我在提示符下输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>whereis cal</span></span></code></pre></div><p>我将看到这个：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/whereis_cal.png?resize=800%2C100&amp;ssl=1" alt="whereis cal output"></p><p>仔细看一下这个回答。答案只在一行里，但它告诉我两件事：</p><ul><li><code>/usr/bin/cal</code> 是 <code>cal</code> 程序所在的地方，以及</li><li><code>/usr/share/man/man1/cal.1.gz</code> 是手册页所在的地方（我也知道手册页是被压缩的，但不用担心 —— <code>man</code> 命令知道如何即时解压）。</li></ul><p><code>whereis</code> 依赖于 <code>PATH</code> 环境变量；它只能告诉你文件在哪里，如果它们在你的 <code>PATH</code> 环境变量中。</p><p>你可能想知道是否有一个与 <code>whereis</code> 相当的 <code>man</code> 命令。没有一个命令可以告诉你可执行文件的位置，但有一个开关可以告诉你手册页的位置。在这个例子中使用 <code>date</code> 命令，如果我们输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>whereis date</span></span></code></pre></div><p>在终端提示符下，我们会看到：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/05/whereis_date.png?resize=800%2C100&amp;ssl=1" alt="whereis date output"></p><p>我们看到 <code>date</code> 程序在 <code>/usr/bin/</code> 目录下，其手册页的名称和位置是：<code>/usr/share/man/man1/date.1.gz</code>。</p><p>我们可以让 <code>man</code> 像 <code>whereis</code> 一样行事，最接近的方法是使用 <code>-w</code> 开关。我们不会得到程序的位置，但我们至少可以得到手册页的位置，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man -w date</span></span></code></pre></div><p>我们将看到这样的返回：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/05/man-w_date-1.png?resize=800%2C100&amp;ssl=1" alt=""></p><p>你知道了 <code>whatis</code> 和 <code>whereis</code>，以及让 <code>man</code> 命令做同样（或接近）事情的方法。我展示了这两种方法，有几个不同的原因。</p><p>多年来，我使用 <code>whatis</code> 和 <code>whereis</code>，因为它们在我的培训手册中。直到最近我才了解到 <code>man -f ...</code> 和 <code>man -w ...</code>。我确信我看了几百次 <code>man</code> 的手册页，但我从未注意到 <code>-f</code> 和 <code>-w</code> 开关。我总是在看手册页的其他东西（例如：<code>man -k ...</code>）。我只专注于我需要找到的东西，而忽略了其他的东西。一旦我找到了我需要的信息，我就会离开这个页面，去完成工作，而不去注意这个命令所提供的其他一些宝贝。</p><p>这没关系，因为这部分就是手册页的作用：帮助你完成工作。</p><p>直到最近我向别人展示如何使用手册页时，我才花时间去阅读 —— “看看还有什么可能” —— 我们才真正注意到关于 <code>man</code> 命令的 <code>-f</code> 和 <code>-w</code> 标记可以做什么的信息。</p><p>不管你使用 Linux 多久了，或者多么有经验，总有一些新东西需要学习。</p><p>手册页会告诉你在完成某项任务时可能需要知道的东西 —— 但它们也有很多内容 —— 足以让你看起来像个魔术师，但前提是你要花时间去读。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>如果你花一些时间和精力在手册页上，你将会取得胜利。你对手册页的熟练程度，将在你掌握 Linux 的过程中发挥巨大作用。</p><hr>`,125)),a("p",null,[e[4]||(e[4]=s("via: ",-1)),d(i,{href:"https://itsfoss.com/linux-man-page-guide/"},{default:t(()=>[...e[3]||(e[3]=[s("https://itsfoss.com/linux-man-page-guide/",-1)])]),_:1})]),a("p",null,[e[9]||(e[9]=s("作者：",-1)),d(i,{href:"https://itsfoss.com/author/bill/"},{default:t(()=>[...e[5]||(e[5]=[s("Bill Dyer",-1)])]),_:1}),e[10]||(e[10]=s(" 选题：",-1)),d(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[6]||(e[6]=[s("lujun9972",-1)])]),_:1}),e[11]||(e[11]=s(" 译者：",-1)),d(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[7]||(e[7]=[s("wxy",-1)])]),_:1}),e[12]||(e[12]=s(" 校对：",-1)),d(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[8]||(e[8]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[15]||(e[15]=s("本文由 ",-1)),d(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[13]||(e[13]=[s("LCTT",-1)])]),_:1}),e[16]||(e[16]=s(" 原创编译，",-1)),d(i,{href:"https://linux.cn/"},{default:t(()=>[...e[14]||(e[14]=[s("Linux中国",-1)])]),_:1}),e[17]||(e[17]=s(" 荣誉推出",-1))])])}const y=o(r,[["render",h]]);export{x as __pageData,y as default};
